function loadAppearance() {
  const fallback = { theme: "black", fog: true, aurora: true, grid: true, particles: true };
  try {
    const stored = JSON.parse(localStorage.getItem(APPEARANCE_KEY) || "{}");
    return {
      theme: Object.hasOwn(THEMES, stored.theme) ? stored.theme : fallback.theme,
      fog: typeof stored.fog === "boolean" ? stored.fog : fallback.fog,
      aurora: typeof stored.aurora === "boolean" ? stored.aurora : fallback.aurora,
      grid: typeof stored.grid === "boolean" ? stored.grid : fallback.grid,
      particles: typeof stored.particles === "boolean" ? stored.particles : fallback.particles,
    };
  } catch (error) {
    console.error("Unable to read saved appearance settings.", error);
    return fallback;
  }
}

function saveAppearance() {
  try {
    localStorage.setItem(APPEARANCE_KEY, JSON.stringify(state.appearance));
  } catch (error) {
    console.error("Unable to save appearance settings.", error);
    showToast("Could not save appearance settings. Check browser storage permissions.");
  }
}

function applyCustomStylesheet() {
  let stylesheet = document.querySelector("#c3-custom-stylesheet");
  if (!state.config.stylesheet) {
    stylesheet?.remove();
    return;
  }
  if (!stylesheet) {
    stylesheet = document.createElement("link");
    stylesheet.id = "c3-custom-stylesheet";
    stylesheet.rel = "stylesheet";
    stylesheet.addEventListener("error", () => {
      console.error("Unable to load the configured custom stylesheet.", state.config.stylesheet);
      showToast("Could not load the custom stylesheet. Check the URL and its availability.");
    });
    stylesheet.href = state.config.stylesheet;
    document.head.append(stylesheet);
    return;
  }
  if (stylesheet.href !== state.config.stylesheet) stylesheet.href = state.config.stylesheet;
}

function applyAppearance() {
  const selectedTheme = Object.hasOwn(THEMES, state.appearance.theme) ? state.appearance.theme : "black";
  document.body.classList.toggle("grid-enabled", state.appearance.grid);
  document.body.classList.toggle("fog-enabled", state.appearance.fog);
  document.body.classList.toggle("aurora-enabled", state.appearance.aurora);
  document.body.classList.toggle("particles-enabled", state.appearance.particles);
  document.body.dataset.theme = selectedTheme;
}

function loadConfig() {
  try {
    const stored = JSON.parse(localStorage.getItem(CONFIG_KEY) || "{}");
    return {
      manga: normalizeBase(stored.manga || ""),
      movies: normalizeBase(stored.movies || ""),
      music: normalizeBase(stored.music || ""),
      gameIndex: normalizeRemoteUrl(stored.gameIndex || DEFAULT_GAME_INDEX, "Games JSON URL"),
      gameBase: normalizeRemoteUrl(stored.gameBase || DEFAULT_GAME_BASE, "Game files URL", true),
      stylesheet: normalizeRemoteUrl(stored.stylesheet || "", "Custom CSS URL"),
    };
  } catch (error) {
    console.error("Unable to read saved C3 settings.", error);
    return { manga: "", movies: "", music: "", gameIndex: DEFAULT_GAME_INDEX, gameBase: DEFAULT_GAME_BASE, stylesheet: "" };
  }
}

function normalizeBase(value) {
  return String(value || "").trim().replace(/\/+$/, "");
}

function normalizeRemoteUrl(value, label, directory = false) {
  const input = String(value || "").trim();
  if (!input) return "";
  let url;
  try {
    url = new URL(input);
  } catch {
    throw new Error(`${label} must be a valid URL.`);
  }
  if (!["http:", "https:"].includes(url.protocol)) {
    throw new Error(`${label} must use HTTP or HTTPS.`);
  }
  if (directory) {
    if (url.search || url.hash) throw new Error(`${label} must not include a query or fragment.`);
    if (!url.pathname.endsWith("/")) url.pathname += "/";
  }
  return url.href;
}

function escapeHTML(value) {
  return String(value ?? "").replace(/[&<>"']/g, (char) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
  })[char]);
}

function showToast(message) {
  toast.textContent = message;
  toast.classList.add("visible");
  clearTimeout(showToast.timer);
  showToast.timer = setTimeout(() => toast.classList.remove("visible"), 3400);
}

function setView(name, { focus = false } = {}) {
  if (!views[name]) return;
  state.view = name;
  document.querySelectorAll(".nav-item").forEach((button) => {
    button.classList.toggle("active", button.dataset.view === name);
  });
  document.querySelector("#current-section").textContent = views[name];
  globalSearch.value = "";
  globalSearch.placeholder = name === "home" || name === "settings" || name === "extensions" || name === "cloud"
    ? "Search this section"
    : `Search ${views[name].toLowerCase()}`;
  history.replaceState(null, "", `#${name}`);
  renderView();
  if (focus) viewRoot.focus();
}

function sectionHeader(label, title, description, action = "") {
  return `<div class="content-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
}

const HOME_PHRASES = [
  "creds to x8rr, thx goat!",
  "jcyms is jail",
  "just this once",
  "I.H in academy 7th is goated.",
];
let homePhraseTimer = null;
function renderHome() {
  viewRoot.innerHTML = '<section class="home-landing" id="home" aria-labelledby="home-title"><h1 id="home-title">C<span>3</span></h1><footer class="home-footer" id="home-footer" aria-live="polite" aria-atomic="true"></footer></section>';
  const footer = viewRoot.querySelector("#home-footer");
  clearInterval(homePhraseTimer);
  let phraseIndex = 0;
  const showPhrase = () => {
    if (!footer.isConnected) {
      clearInterval(homePhraseTimer);
      homePhraseTimer = null;
      return;
    }
    footer.classList.remove("is-changing");
    footer.textContent = HOME_PHRASES[phraseIndex];
    void footer.offsetWidth;
    footer.classList.add("is-changing");
    phraseIndex = (phraseIndex + 1) % HOME_PHRASES.length;
  };
  showPhrase();
  homePhraseTimer = window.setInterval(showPhrase, 4000);
}

function renderApps(query = "") {
  viewRoot.innerHTML = `
    ${sectionHeader("YOUR SHORTCUTS", "Apps", "A collection of useful places from the old C3 app hub. App shortcuts open the official site in a new tab.")}
    <div class="toolbar"><label class="search-form"><input id="apps-query" type="search" value="${escapeHTML(query)}" placeholder="Find an app..." aria-label="Find an app"></label><span class="pill">${APP_CATALOG.length} shortcuts</span></div>
    <div id="apps-results">${renderAppCards(query)}</div>`;
}

function renderAppCards(query = "") {
  const normalizedQuery = query.trim().toLowerCase();
  const apps = APP_CATALOG.filter((app) => `${app.name} ${app.category}`.toLowerCase().includes(normalizedQuery));
  if (!apps.length) return emptyState("No apps found", "Try another search.");
  return `<div class="app-grid">${apps.map((app) => `
    <a class="app-card" href="${app.url}" target="_blank" rel="noopener noreferrer">
      <span class="app-card-open" aria-hidden="true">↗</span>
      <img src="${appImage(app.image)}" alt="" loading="lazy">
      <span class="app-card-name">${escapeHTML(app.name)}</span>
      <span class="app-card-category">${escapeHTML(app.category)}</span>
    </a>`).join("")}</div>`;
}

function renderGames() {
  viewRoot.innerHTML = `
    ${sectionHeader("THE ARCADE", "Games", "Load a remote JSON catalog and its hosted game files. You can change both sources in Settings.")}
    <div class="toolbar"><form id="games-search" class="search-form"><input id="games-query" type="search" placeholder="Find a game..." aria-label="Find a game"><button class="button" type="submit">Search</button></form><span class="pill">Remote catalog</span></div>
    <div id="games-results" class="loading-state">Loading the game catalog…</div>`;
  loadGames();
}

async function loadGames() {
  const target = document.querySelector("#games-results");
  if (!target) return;
  if (!state.games.length && !state.gameError) {
    try {
      const response = await fetch(state.config.gameIndex || DEFAULT_GAME_INDEX);
      if (!response.ok) throw new Error(`Game index returned ${response.status}.`);
      const data = await response.json();
      if (!Array.isArray(data)) throw new Error("The game index did not return a list.");
      state.games = data.filter((game) => game && typeof game.name === "string" && typeof game.url === "string");
      if (!state.games.length) throw new Error("The game index was empty or had an unsupported format.");
    } catch (error) {
      state.gameError = error.message || "Could not load the game index.";
      console.error("Unable to load the configured game catalog.", error);
    }
  }
  if (state.gameError) {
    target.innerHTML = emptyState("Games could not load", `${escapeHTML(state.gameError)} Check your connection and try again.`, '<button class="button small" data-retry-games>Retry</button>');
    return;
  }
  filterGameCards();
}

function filterGameCards() {
  const target = document.querySelector("#games-results");
  if (!target) return;
  const query = (document.querySelector("#games-query")?.value || "").trim().toLowerCase();
  const games = state.games.filter((game) => game.name.toLowerCase().includes(query));
  if (!games.length) {
    target.innerHTML = emptyState("No games found", "Try a different search.");
    return;
  }
  target.innerHTML = `<div class="card-grid">${games.map((game, index) => `
    <article class="media-card">
      <div class="media-art">${game.img ? `<img src="${escapeHTML(resolveGamePath(game.img))}" alt="" loading="lazy" onerror="this.remove();this.nextElementSibling.hidden=false">` : ""}<span class="art-fallback" ${game.img ? "hidden" : ""}>✣</span></div>
      <div class="media-card-body"><h3 title="${escapeHTML(game.name)}">${escapeHTML(game.name)}</h3><p>Game collection</p><div class="card-actions"><button class="button small primary" data-play-game="${index}" data-game-name="${escapeHTML(game.name)}" data-game-url="${escapeHTML(resolveGamePath(game.url))}">Play</button></div></div>
    </article>`).join("")}</div>`;
}

function resolveGamePath(path) {
  const cleanPath = String(path).replace(/^\/+/, "");
  return new URL(cleanPath, state.config.gameBase || DEFAULT_GAME_BASE).href;
}

async function launchGame(url, name) {
  let safeUrl;
  try {
    safeUrl = new URL(url);
    if (safeUrl.origin !== new URL(state.config.gameBase || DEFAULT_GAME_BASE).origin) {
      throw new Error("That game link is outside the configured game host.");
    }
  } catch (error) {
    showToast(error.message || "That game link is invalid.");
    return;
  }

  const dialog = document.createElement("dialog");
  dialog.className = "player-dialog game-dialog";
  dialog.innerHTML = `<div class="dialog-top"><div><span class="eyebrow">SERAPH · GMSHELF</span><h2>${escapeHTML(name)}</h2></div><button class="icon-button dialog-close" aria-label="Close game"><svg class="lucide-icon" width="18" height="18" aria-hidden="true" focusable="false" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" > <path d="M18 6 6 18" /> <path d="m6 6 12 12" /> </svg></button></div><p class="game-loading" role="status">Loading game…</p><iframe class="game-frame" title="${escapeHTML(name)}" sandbox="allow-scripts allow-forms allow-pointer-lock allow-modals allow-downloads" allow="fullscreen; autoplay; gamepad" allowfullscreen></iframe>`;
  const frame = dialog.querySelector(".game-frame");
  const status = dialog.querySelector(".game-loading");
  const controller = new AbortController();
  let closed = false;
  let gameBlobUrl = "";

  dialog.querySelector(".dialog-close").addEventListener("click", () => dialog.close());
  dialog.addEventListener("close", () => {
    closed = true;
    controller.abort();
    frame.src = "about:blank";
    if (gameBlobUrl) URL.revokeObjectURL(gameBlobUrl);
    dialog.remove();
  }, { once: true });
  dialog.addEventListener("click", (event) => {
    if (event.target === dialog) dialog.close();
  });
  document.body.append(dialog);
  dialog.showModal();

  try {
    const response = await fetch(safeUrl.href, { headers: { Accept: "text/html" }, signal: controller.signal });
    if (!response.ok) throw new Error(`Game file returned HTTP ${response.status}.`);
    const source = await response.text();
    if (closed) return;
    const baseTag = `<base href="${escapeHTML(safeUrl.href)}">`;
    const documentHtml = /<head\b[^>]*>/i.test(source)
      ? source.replace(/<head\b[^>]*>/i, (head) => `${head}${baseTag}`)
      : `<!doctype html><html><head>${baseTag}</head><body>${source}</body></html>`;
    gameBlobUrl = URL.createObjectURL(new Blob([documentHtml], { type: "text/html" }));
    frame.src = gameBlobUrl;
    status.hidden = true;
  } catch (error) {
    if (closed) return;
    status.textContent = `Could not load this game: ${error.message || "Unknown error"} Check that the game host allows browser requests.`;
    console.error("Unable to load game HTML.", error);
  }
}

function renderMovies() {
  viewRoot.innerHTML = `
    ${sectionHeader("THE SCREENING ROOM", "Movies & TV", "Search titles and play them using the x8rr/movies API. This frontend needs a self-hosted API URL and a configured TMDB key on that server.")}
    ${serviceNotice("movies", "x8rr/movies", "Your movies API base URL is not set.")}
    <div class="toolbar"><form id="movies-search" class="search-form"><input id="movies-query" type="search" placeholder="Search movies or TV..." aria-label="Search movies or TV"><button class="button" type="submit">Search</button></form><div class="pill-tabs"><button class="pill-tab active" data-movie-type="movie">Movies</button><button class="pill-tab" data-movie-type="tv">TV</button></div></div>
    <div id="movies-results" class="loading-state">${state.config.movies ? "Loading trending titles…" : "Connect your movies service to get started."}</div>`;
  if (state.config.movies) loadMovies();
}

async function loadMovies(query = "") {
  state.movieQuery = query;
  const target = document.querySelector("#movies-results");
  if (!target) return;
  target.innerHTML = `<div class="loading-state">${query ? "Searching…" : "Loading trending titles…"}</div>`;
  try {
    const type = document.querySelector("[data-movie-type].active")?.dataset.movieType || "movie";
    const path = query
      ? `/api/search/${type}?query=${encodeURIComponent(query)}`
      : `/api/trending/${type}/week`;
    const data = await apiJSON("movies", path);
    state.movieItems = listFrom(data);
    renderMovieCards();
  } catch (error) {
    renderServiceError(target, error, "Check the API URL, server status, and CORS configuration.");
  }
}

function renderMovieCards() {
  const target = document.querySelector("#movies-results");
  if (!target) return;
  if (!state.movieItems.length) {
    target.innerHTML = emptyState("Nothing found", "Try another title or switch between Movies and TV.");
    return;
  }
  const type = document.querySelector("[data-movie-type].active")?.dataset.movieType || "movie";
  target.innerHTML = `<div class="card-grid">${state.movieItems.map((item) => {
    const id = item.id ?? item.tmdbId;
    const title = item.title || item.name || "Untitled";
    const poster = imageURL(item.poster_path || item.poster || item.cover);
    const year = (item.release_date || item.first_air_date || "").slice(0, 4);
    return `<article class="media-card">
      <div class="media-art">${poster ? `<img src="${escapeHTML(poster)}" alt="" loading="lazy" onerror="this.remove()">` : '<span class="art-fallback">▣</span>'}</div>
      <div class="media-card-body"><h3 title="${escapeHTML(title)}">${escapeHTML(title)}</h3><p>${escapeHTML(year || (type === "tv" ? "TV series" : "Movie"))}</p><div class="card-actions">${type === "tv"
        ? `<button class="button small primary" data-movie-details="${escapeHTML(id)}" data-movie-title="${escapeHTML(title)}">Seasons</button>`
        : `<button class="button small primary" data-movie-id="${escapeHTML(id)}" data-movie-title="${escapeHTML(title)}" data-movie-type="${type}">Play</button>`}</div></div>
    </article>`;
  }).join("")}</div>`;
}

async function playMovie(id, title, type, season = 1, episode = 1) {
  if (!id) return showToast("This result does not include a movie ID.");
  const dialog = playerDialog;
  const video = document.querySelector("#video-player");
  const message = document.querySelector("#player-message");
  document.querySelector("#player-title").textContent = title;
  message.textContent = "Finding a stream…";
  video.pause();
  video.removeAttribute("src");
  video.load();
  dialog.showModal();
  try {
    const path = type === "tv"
      ? `/api/stream/tv/${encodeURIComponent(id)}/${encodeURIComponent(season)}/${encodeURIComponent(episode)}`
      : `/api/stream/movie/${encodeURIComponent(id)}`;
    const response = await apiJSON("movies", path);
    const data = response?.data || response;
    const sources = listFrom(data, ["sources"]);
    const source = typeof data === "string" ? data : (sources[0]?.url || sources[0]?.file || data.url || data.stream || data.m3u8 || data.source);
    if (typeof source !== "string" || !source) throw new Error("The stream endpoint returned no playable URL.");
    const sourceURL = new URL(source, `${state.config.movies}/`);
    if (!["http:", "https:"].includes(sourceURL.protocol)) throw new Error("The movies API returned an unsupported stream URL.");
    const isHls = /\.m3u8(?:$|\?)/i.test(sourceURL.href);
    const isAlreadyProxied = sourceURL.pathname.endsWith("/api/proxy");
    const streamUrl = isHls && !isAlreadyProxied
      ? `${state.config.movies}/api/proxy?url=${encodeURIComponent(sourceURL.href)}`
      : sourceURL.href;
    if (isHls) {
      if (video.canPlayType("application/vnd.apple.mpegurl")) {
        video.src = streamUrl;
      } else {
        await loadHls();
        if (!window.Hls.isSupported()) throw new Error("This browser cannot play HLS streams.");
        const hls = new window.Hls();
        hls.loadSource(streamUrl);
        hls.attachMedia(video);
        dialog.addEventListener("close", () => hls.destroy(), { once: true });
      }
    } else {
      video.src = streamUrl;
    }
    message.textContent = "Stream supplied by your configured movies server.";
    await video.play().catch(() => {});
  } catch (error) {
    message.textContent = error.message || "Unable to play this title.";
    console.error("Movie playback failed.", error);
  }
}

async function openTvDetails(id, title) {
  if (!id) return showToast("This result does not include a TV ID.");
  document.querySelector("#detail-title").textContent = title;
  const content = document.querySelector("#detail-content");
  content.innerHTML = '<div class="loading-state">Loading seasons…</div>';
  detailDialog.showModal();
  try {
    const data = await apiJSON("movies", `/api/tv/${encodeURIComponent(id)}`);
    const series = data.tv || data.item || data.data || data;
    const seasons = (series.seasons || []).filter((season) => Number(season.season_number ?? season.number) > 0);
    if (!seasons.length) throw new Error("The TV details response contains no seasons.");
    content.dataset.tvId = String(id);
    content.dataset.tvTitle = title;
    content.innerHTML = `<div class="toolbar"><label class="field season-field"><span class="small-note">Season</span><select id="tv-season">${seasons.map((season) => `<option value="${escapeHTML(season.season_number ?? season.number)}">${escapeHTML(season.name || `Season ${season.season_number ?? season.number}`)}</option>`).join("")}</select></label></div><div id="tv-episodes" class="loading-state">Loading episodes…</div>`;
    await loadTvEpisodes(id, seasons[0].season_number ?? seasons[0].number);
  } catch (error) {
    renderServiceError(content, error, "Check the TV details endpoint and server.");
  }
}

async function loadTvEpisodes(id, season) {
  const target = document.querySelector("#tv-episodes");
  if (!target) return;
  target.innerHTML = '<div class="loading-state">Loading episodes…</div>';
  try {
    const data = await apiJSON("movies", `/api/tv/${encodeURIComponent(id)}/season/${encodeURIComponent(season)}`);
    const episodes = listFrom(data, ["episodes"]);
    if (!episodes.length) {
      target.innerHTML = emptyState("No episodes found", "This season did not return any episodes.");
      return;
    }
    target.innerHTML = `<div class="chapter-list">${episodes.map((episode, index) => {
      const number = episode.episode_number ?? episode.episode ?? index + 1;
      return `<button class="chapter-button" data-tv-episode="${escapeHTML(number)}" data-tv-season="${escapeHTML(season)}"><span>Episode ${escapeHTML(number)}${episode.name ? ` — ${escapeHTML(episode.name)}` : ""}</span><span>Play ↗</span></button>`;
    }).join("")}</div>`;
  } catch (error) {
    renderServiceError(target, error, "Check the season endpoint and server.");
  }
}

function loadHls() {
  if (window.Hls) return Promise.resolve();
  return Promise.reject(new Error("The bundled HLS playback library is unavailable."));
}

