  viewRoot.innerHTML = `
    ${sectionHeader("ANIME DISCOVERY", "Anime", "Search AniList for series, seasons, and official watch links.")}
    <form id="anime-search" class="search-form anime-search"><input id="anime-query" type="search" value="${escapeHTML(animeQuery)}" placeholder="Search anime..." aria-label="Search anime"><button class="button primary" type="submit">Search</button></form>
    <p class="small-note anime-note">Catalog and metadata from AniList. Watch links open the services listed by AniList; episodes are not hosted here.</p>
    <div id="anime-results" class="loading-state">Loading popular anime…</div>`;
  loadAnime(animeQuery);
}

async function loadAnime(query = "") {
  animeQuery = query.trim();
  const target = document.querySelector("#anime-results");
  if (!target) return;
  const requestId = ++animeRequestId;
  target.innerHTML = `<div class="loading-state">${animeQuery ? "Searching AniList…" : "Loading popular anime…"}</div>`;
  try {
    const sort = animeQuery ? "SEARCH_MATCH" : "POPULARITY_DESC";
    const response = await fetch("https://graphql.anilist.co", {
      method: "POST",
      headers: { "Content-Type": "application/json", Accept: "application/json" },
      body: JSON.stringify({
        query: `query ($search: String) { Page(perPage: 24) { media(search: $search, type: ANIME, sort: ${sort}, isAdult: false) { id title { english romaji } coverImage { large } format episodes seasonYear status averageScore description siteUrl externalLinks { site url type } } } }`,
        variables: { search: animeQuery || null },
      }),
    });
    if (!response.ok) throw new Error(`AniList returned HTTP ${response.status}.`);
    const data = await response.json();
    if (requestId !== animeRequestId) return;
    if (data.errors?.length) throw new Error(data.errors[0].message || "AniList could not complete the search.");
    animeItems = data.data?.Page?.media;
    if (!Array.isArray(animeItems)) throw new Error("AniList returned an unsupported response.");
    renderAnimeCards();
  } catch (error) {
    if (requestId !== animeRequestId) return;
    renderServiceError(target, error, "Check your connection or try again later.");
  }
}

function renderAnimeCards() {
  const target = document.querySelector("#anime-results");
  if (!target) return;
  if (!animeItems.length) {
    target.innerHTML = emptyState("No anime found", "Try another title.");
    return;
  }
  target.innerHTML = `<div class="card-grid anime-grid">${animeItems.map((item) => {
    const title = item.title?.english || item.title?.romaji || "Untitled";
    const cover = item.coverImage?.large || "";
    const details = [item.seasonYear, item.format?.replaceAll("_", " "), item.episodes ? `${item.episodes} episodes` : ""].filter(Boolean).join(" · ");
    const summary = String(item.description || "").replace(/<[^>]*>/g, " ").replace(/&nbsp;/gi, " ").replace(/\s+/g, " ").trim().slice(0, 150);
    const streamingLinks = (item.externalLinks || []).filter((link) => link.type === "STREAMING" && /^https?:\/\//i.test(link.url || ""));
    const links = streamingLinks.slice(0, 2).map((link) => `<a class="button small" href="${escapeHTML(link.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(link.site || "Watch")} ↗</a>`).join("");
    const aniListLink = /^https?:\/\//i.test(item.siteUrl || "") ? item.siteUrl : `https://anilist.co/anime/${encodeURIComponent(item.id)}`;
    return `<article class="media-card anime-card">
      <div class="media-art">${cover ? `<img src="${escapeHTML(cover)}" alt="" loading="lazy" onerror="this.remove()">` : '<span class="art-fallback">◈</span>'}</div>
      <div class="media-card-body"><h3 title="${escapeHTML(title)}">${escapeHTML(title)}</h3><p>${escapeHTML(details || item.status || "Anime")}</p>${summary ? `<p class="anime-summary">${escapeHTML(summary)}</p>` : ""}<div class="card-actions">${links}<a class="button small primary" href="${escapeHTML(aniListLink)}" target="_blank" rel="noopener noreferrer">Details ↗</a></div></div>
    </article>`;
  }).join("")}</div>`;
}

function renderBrowser() {
  viewRoot.innerHTML = `
    ${sectionHeader("OPEN WEB", "Browser", "Open a website in a regular browser tab.")}
    <section class="browser-panel">
      <form id="browser-search" class="browser-address"><label for="browser-url">Website address</label><div><input id="browser-url" type="text" inputmode="url" autocomplete="url" placeholder="https://example.com" aria-label="Website address"><button class="button primary" type="submit">Open tab ↗</button></div></form>
      <p class="small-note">This uses normal browser navigation; sites may block being embedded. No proxy or restriction-bypass service is used.</p>
      <div class="browser-bookmarks" aria-label="Quick links">${browserBookmarks.map((bookmark) => `<a class="browser-bookmark" href="${bookmark.url}" target="_blank" rel="noopener noreferrer"><span aria-hidden="true">↗</span>${bookmark.label}</a>`).join("")}</div>
    </section>`;
}

function openBrowserUrl(value) {
  const input = String(value || "").trim();
  if (!input) {
    showToast("Enter a website address first.");
    return;
  }
  let destination;
  try {
    destination = new URL(/^[a-z][a-z0-9+.-]*:/i.test(input) ? input : `https://${input}`);
  } catch {
    showToast("Enter a valid website address.");
    return;
  }
  if (!["http:", "https:"].includes(destination.protocol) || destination.username || destination.password) {
    showToast("Only public HTTP and HTTPS addresses can be opened.");
    return;
  }
  window.open(destination.href, "_blank", "noopener,noreferrer");
}

function renderView() {
  switch (state.view) {
    case "games": renderGames(); break;
    case "apps": renderApps(); break;
    case "movies": renderMovies(); break;
    case "manga": renderManga(); break;
    case "anime": renderAnime(); break;
    case "browser": renderBrowser(); break;
    case "music": renderMusic(); break;
    case "cloud": renderCloud(); break;
    case "extensions": renderExtensions(); break;
    case "settings": renderSettings(); break;
    default: renderHome();
  }
}

function emptyState(title, description, action = "") {
  return `<div class="empty-state"><strong>${escapeHTML(title)}</strong><p>${escapeHTML(description)}</p>${action ? `<div class="empty-action">${action}</div>` : ""}</div>`;
}

function listFrom(data, preferred = []) {
  if (Array.isArray(data)) return data;
  for (const key of [...preferred, "items", "results", "tracks", "data"]) {
    if (Array.isArray(data?.[key])) return data[key];
  }
  if (data?.data && typeof data.data === "object") return listFrom(data.data, preferred);
  return [];
}

function imageURL(value) {
  if (!value || typeof value !== "string") return "";
  if (/^https?:\/\//i.test(value)) return value;
  if (value.startsWith("/")) return `https://image.tmdb.org/t/p/w500${value}`;
  return value;
}

function mangaImageURL(value) {
  if (!value || typeof value !== "string") return "";
  if (state.mangaSource !== "pill") return imageURL(value);
  const image = /^https?:\/\//i.test(value) ? value : new URL(value, `${state.config.manga}/`).href;
  return `${state.config.manga}/img?u=${encodeURIComponent(image)}`;
}

function slugify(value) {
  return String(value || "").toLowerCase().trim().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

function renderServiceError(target, error, advice) {
  console.error("Service request failed.", error);
  target.innerHTML = emptyState("Service request failed", `${error.message || "Unknown error"} ${advice}`);
}

async function apiJSON(service, path) {
  const base = state.config[service];
  if (!base) throw new Error(`Set the ${service} API URL in Settings first.`);
  const url = new URL(`${base}${path.startsWith("/") ? path : `/${path}`}`);
  if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error("API URLs must use HTTP or HTTPS.");
  const response = await fetch(url, { headers: { Accept: "application/json" } });
  if (!response.ok) throw new Error(`API returned ${response.status} ${response.statusText}.`);
  return response.json();
}

document.addEventListener("click", async (event) => {
  const go = event.target.closest("[data-go]");
  if (go) return setView(go.dataset.go);
  const nav = event.target.closest(".nav-item");
  if (nav) return setView(nav.dataset.view);
  if (event.target.closest("#settings-shortcut")) return setView("settings");
  if (event.target.closest("[data-close-dialog]")) {
    event.target.closest("dialog").close();
    return;
  }
  if (event.target.closest("[data-retry-games]")) {
    state.gameError = "";
    state.games = [];
    return loadGames();
  }
  const game = event.target.closest("[data-game-url]");
  if (game) return launchGame(game.dataset.gameUrl, game.dataset.gameName);
  const movieType = event.target.closest("[data-movie-type]");
  if (movieType) {
    document.querySelectorAll("[data-movie-type]").forEach((button) => button.classList.toggle("active", button === movieType));
    return loadMovies(state.movieQuery);
  }
  const movie = event.target.closest("[data-movie-id]");
  if (movie) return playMovie(movie.dataset.movieId, movie.dataset.movieTitle, movie.dataset.movieType);
  const tv = event.target.closest("[data-movie-details]");
  if (tv) return openTvDetails(tv.dataset.movieDetails, tv.dataset.movieTitle);
  const episode = event.target.closest("[data-tv-episode]");
  if (episode) {
    const content = document.querySelector("#detail-content");
    return playMovie(content.dataset.tvId, `${content.dataset.tvTitle} · S${episode.dataset.tvSeason}E${episode.dataset.tvEpisode}`, "tv", episode.dataset.tvSeason, episode.dataset.tvEpisode);
  }
  const mangaSource = event.target.closest("[data-manga-source]");
  if (mangaSource) {
    state.mangaSource = mangaSource.dataset.mangaSource;
    return renderManga();
  }
  const manga = event.target.closest("[data-manga-index]");
  if (manga) return openMangaDetails(state.mangaItems[Number(manga.dataset.mangaIndex)]);
  const chapter = event.target.closest("[data-chapter-index]");
  if (chapter) {
    const chapters = JSON.parse(document.querySelector("#detail-content").dataset.chapters || "[]");
    return readChapter(chapters[Number(chapter.dataset.chapterIndex)]);
  }
  if (event.target.closest("[data-return-details]")) return openMangaDetails({
    id: document.querySelector("#detail-content").dataset.seriesId,
    title: document.querySelector("#detail-title").textContent,
    slug: document.querySelector("#detail-content").dataset.seriesSlug,
  });
  const track = event.target.closest("[data-track-index]");
  if (track) return playTrack(state.musicItems[Number(track.dataset.trackIndex)]);
  if (event.target.closest("[data-clear-config]")) {
    try {
      localStorage.removeItem(CONFIG_KEY);
      state.config = { manga: "", movies: "", music: "", gameIndex: DEFAULT_GAME_INDEX, gameBase: DEFAULT_GAME_BASE, stylesheet: "" };
      state.games = [];
      state.gameError = "";
      applyCustomStylesheet();
      renderSettings();
      if (state.view === "games") loadGames();
      showToast("Saved settings reset to defaults.");
    } catch (error) {
      console.error("Unable to clear C3 API settings.", error);
      showToast("Could not clear settings. Check browser storage permissions.");
    }
  }
});

document.addEventListener("change", (event) => {
  if (event.target.id === "tv-season") {
    const id = document.querySelector("#detail-content").dataset.tvId;
    loadTvEpisodes(id, event.target.value);
  } else if (event.target.id === "theme-choice") {
    state.appearance.theme = Object.hasOwn(THEMES, event.target.value) ? event.target.value : "c3";
    applyAppearance();
    saveAppearance();
  } else if (["grid-toggle", "fog-toggle", "aurora-toggle", "particles-toggle"].includes(event.target.id)) {
    state.appearance[event.target.name] = event.target.checked;
    applyAppearance();
    saveAppearance();
  }
});

document.addEventListener("submit", (event) => {
  if (event.target.id === "games-search") {
    event.preventDefault();
    filterGameCards();
  } else if (event.target.id === "movies-search") {
    event.preventDefault();
    loadMovies(document.querySelector("#movies-query").value.trim());
  } else if (event.target.id === "manga-search") {
    event.preventDefault();
    loadManga(document.querySelector("#manga-query").value.trim());
  } else if (event.target.id === "music-search") {
    event.preventDefault();
    loadMusic(document.querySelector("#music-query").value.trim());
  } else if (event.target.id === "anime-search") {
    event.preventDefault();
    loadAnime(document.querySelector("#anime-query").value);
  } else if (event.target.id === "browser-search") {
    event.preventDefault();
    openBrowserUrl(document.querySelector("#browser-url").value);
  } else if (event.target.id === "settings-form") {
    event.preventDefault();
    const formData = new FormData(event.target);
    let next;
    try {
      next = {
        ...Object.fromEntries(["manga", "movies", "music"].map((key) => [key, normalizeBase(formData.get(key))])),
        gameIndex: normalizeRemoteUrl(formData.get("gameIndex") || DEFAULT_GAME_INDEX, "Games JSON URL"),
        gameBase: normalizeRemoteUrl(formData.get("gameBase") || DEFAULT_GAME_BASE, "Game files base URL", true),
        stylesheet: normalizeRemoteUrl(formData.get("stylesheet"), "Optional CSS URL"),
      };
      for (const key of ["manga", "movies", "music"]) {
        if (next[key] && !/^https?:\/\//i.test(next[key])) {
          showToast(`${key} API URL must start with http:// or https://.`);
          return;
        }
      }
    } catch (error) {
      showToast(error.message);
      return;
    }
    try {
      localStorage.setItem(CONFIG_KEY, JSON.stringify(next));
      state.config = next;
      state.games = [];
      state.gameError = "";
      applyCustomStylesheet();
      if (state.view === "games") loadGames();
      showToast("Settings saved in this browser.");
    } catch (error) {
      console.error("Unable to save C3 API settings.", error);
      showToast("Could not save settings. Check browser storage permissions.");
    }
  }
});

globalSearch.addEventListener("input", () => {
  const input = globalSearch.value.trim();
  if (state.view === "games" && state.games.length) {
    const queryInput = document.querySelector("#games-query");
    if (queryInput) queryInput.value = input;
    filterGameCards();
  } else if (state.view === "movies" && state.config.movies) {
    clearTimeout(globalSearch.timer);
    globalSearch.timer = setTimeout(() => loadMovies(input), 280);
  } else if (state.view === "manga" && state.config.manga) {
    clearTimeout(globalSearch.timer);
    globalSearch.timer = setTimeout(() => loadManga(input), 280);
  } else if (state.view === "music" && state.config.music) {
    clearTimeout(globalSearch.timer);
    globalSearch.timer = setTimeout(() => loadMusic(input), 280);
  } else if (state.view === "anime") {
    clearTimeout(globalSearch.timer);
    globalSearch.timer = setTimeout(() => loadAnime(input), 280);
  } else if (state.view === "apps") {
    const queryInput = document.querySelector("#apps-query");
    if (queryInput) queryInput.value = input;
    const results = document.querySelector("#apps-results");
    if (results) results.innerHTML = renderAppCards(input);
  }
});

document.addEventListener("input", (event) => {
  if (event.target.id === "apps-query") {
    const results = document.querySelector("#apps-results");
    if (results) results.innerHTML = renderAppCards(event.target.value);
  }
});

document.addEventListener("keydown", (event) => {
  if (event.key === "/" && !["INPUT", "TEXTAREA"].includes(document.activeElement.tagName)) {
    event.preventDefault();
    globalSearch.focus();
  }
  if (event.key === "Escape" && playerDialog.open) {
    document.querySelector("#video-player").pause();
  }
});

playerDialog.addEventListener("close", () => {
  const video = document.querySelector("#video-player");
  video.pause();
  video.removeAttribute("src");
  video.load();
});

document.querySelector("#audio-player").addEventListener("error", () => {
  if (audio.currentSrc) showToast("The music server returned an audio stream this browser could not play.");
});

const initialView = location.hash.slice(1);
applyAppearance();
applyCustomStylesheet();
setView(views[initialView] ? initialView : "home");
